  3	final class BellmanFord {
  4	    private static final int INF = 100_000_000;
  5	    private static final int NEGATIVE_CYCLE_MARKER = -1;
  6	    private static final int FROM_INDEX = 0;
  7	    private static final int TO_INDEX = 1;
  8	    private static final int WEIGHT_INDEX = 2;
  9	    private static final int EDGE_FIELD_COUNT = 3;
 10	
 11	    private BellmanFord() {
 12	    }
 13	
 14	    static int[] bellmanFord(int vertexCount, int[][] edgeData, int source) {
 15	        Graph graph = Graph.from(vertexCount, edgeData);
 16	        graph.validateSource(source);
 17	        return shortestPathsFrom(graph, source);
 18	    }
 19	
 20	    private static int[] shortestPathsFrom(Graph graph, int source) {
 21	        int[] distances = initialDistances(graph.vertexCount, source);
 22	
 23	        for (int pass = 1; pass < graph.vertexCount; pass++) {
 24	            if (!relaxEdges(graph.edges, distances)) {
 25	                break;
 26	            }
 27	        }
 28	
 29	        if (hasReachableNegativeCycle(graph.edges, distances)) {
 30	            return negativeCycleResult();
 31	        }
 32	
 33	        return distances;
 34	    }
 35	
 36	    private static int[] initialDistances(int vertexCount, int source) {
 37	        int[] distances = new int[vertexCount];
 38	        Arrays.fill(distances, INF);
 39	        distances[source] = 0;
 40	        return distances;
 41	    }
 42	
 43	    private static int[] negativeCycleResult() {
 44	        return new int[]{NEGATIVE_CYCLE_MARKER};
 45	    }
 46	
 47	    private static boolean relaxEdges(Edge[] edges, int[] distances) {
 48	        boolean changed = false;
 49	
 50	        for (Edge edge : edges) {
 51	            if (edge.relax(distances)) {
 52	                changed = true;
 53	            }
 54	        }
 55	
 56	        return changed;
 57	    }
 58	
 59	    private static boolean hasReachableNegativeCycle(Edge[] edges, int[] distances) {
 60	        for (Edge edge : edges) {
 61	            if (edge.canRelax(distances)) {
 62	                return true;
 63	            }
 64	        }
 65	
 66	        return false;
 67	    }
 68	
 69	    private static String formatDistances(int[] distances) {
 70	        StringBuilder output = new StringBuilder();
 71	        for (int distance : distances) {
 72	            output.append(distance).append(' ');
 73	        }
 74	
 75	        return output.toString();
 76	    }
 77	
 78	    private static final class Edge {
 79	        private final int from;
 80	        private final int to;
 81	        private final int weight;
 82	
 83	        private Edge(int from, int to, int weight) {
 84	            this.from = from;
 85	            this.to = to;
 86	            this.weight = weight;
 87	        }
 88	
 89	        private boolean isWithin(int vertexCount) {
 90	            return from >= 0 && from < vertexCount && to >= 0 && to < vertexCount;
 91	        }
 92	
 93	        private boolean relax(int[] distances) {
 94	            if (!canRelax(distances)) {
 95	                return false;
 96	            }
 97	
 98	            distances[to] = distances[from] + weight;
 99	            return true;
100	        }
101	
102	        private boolean canRelax(int[] distances) {
103	            return distances[from] != INF && distances[from] + weight < distances[to];
104	        }
105	    }
106	
107	    private static final class Graph {
108	        private final int vertexCount;
109	        private final Edge[] edges;
110	
111	        private Graph(int vertexCount, Edge[] edges) {
112	            this.vertexCount = vertexCount;
113	            this.edges = edges;
114	        }
115	
116	        private static Graph from(int vertexCount, int[][] edgeData) {
117	            if (vertexCount < 0) {
118	                throw new IllegalArgumentException("Vertex count cannot be negative");
119	            }
120	
121	            if (edgeData == null) {
122	                throw new IllegalArgumentException("Edges cannot be null");
123	            }
124	
125	            Edge[] edges = new Edge[edgeData.length];
126	            for (int i = 0; i < edgeData.length; i++) {
127	                edges[i] = parseEdge(vertexCount, edgeData[i], i);
128	            }
129	
130	            return new Graph(vertexCount, edges);
131	        }
132	
133	        private static Edge parseEdge(int vertexCount, int[] edgeData, int index) {
134	            if (edgeData == null || edgeData.length != EDGE_FIELD_COUNT) {
135	                throw new IllegalArgumentException("Edge " + index + " must contain from, to, and weight");
136	            }
137	
138	            Edge edge = new Edge(edgeData[FROM_INDEX], edgeData[TO_INDEX], edgeData[WEIGHT_INDEX]);
139	            if (!edge.isWithin(vertexCount)) {
140	                throw new IllegalArgumentException("Edge " + index + " references a vertex outside the graph");
141	            }
142	
143	            return edge;
144	        }
145	
146	        private void validateSource(int source) {
147	            if (source < 0 || source >= vertexCount) {
148	                throw new IllegalArgumentException("Source vertex is out of range");
149	            }
150	        }
151	    }
152	
153	    public static void main(String[] args) {
154	
155	        int vertexCount = 5;
156	
157	        int[][] edges = new int[][] {
158	            {1, 3, 2},
159	            {4, 3, -1},
160	            {2, 4, 1},
161	            {1, 2, 1},
162	            {0, 1, 5}
163	        };
164	
165	        int source = 0;
166	
167	        int[] distances = bellmanFord(vertexCount, edges, source);
168	
169	        System.out.print(formatDistances(distances));
170	    }
171	}

